#[test]
fn appsubst_language_instantiates() {
    let lang = AppSubstLanguage;
    assert_eq!(lang.name(), "AppSubst");
}

#[test]
fn appsubst_metadata_populated() {
    let lang = AppSubstLanguage;
    let meta = lang.metadata();
    assert!(!meta.types().is_empty(), "language should have at least one type");
    assert!(!meta.terms().is_empty(), "language should have at least one term");
}

#[test]
fn unit_appsubst_t_abs() {
    mettail_runtime::clear_var_cache();
    let term = T::Abs(mettail_runtime::Scope::new(
        mettail_runtime::Binder(mettail_runtime::get_or_create_var("a")),
        std::sync::Arc::new(T::TVar(mettail_runtime::OrdVar(mettail_runtime::Var::Free(
            mettail_runtime::get_or_create_var("a"),
        )))),
    ));
    let displayed = format!("{}", term);
    assert!(!displayed.is_empty(), "Display should produce non-empty output for Abs");
}

#[test]
fn unit_appsubst_t_ap() {
    mettail_runtime::clear_var_cache();
    let term = T::Ap(
        std::sync::Arc::new(T::TVar(mettail_runtime::OrdVar(mettail_runtime::Var::Free(
            mettail_runtime::get_or_create_var("a"),
        )))),
        std::sync::Arc::new(T::TVar(mettail_runtime::OrdVar(mettail_runtime::Var::Free(
            mettail_runtime::get_or_create_var("a"),
        )))),
    );
    let displayed = format!("{}", term);
    assert!(!displayed.is_empty(), "Display should produce non-empty output for Ap");
    if let Ok(parsed) = T::parse(&displayed) {
        let re_displayed = format!("{}", parsed);
        assert_eq!(
            displayed, re_displayed,
            "Roundtrip failed for Ap: {} != {}",
            displayed, re_displayed
        );
    }
}

